-- 17A P3 step (i): dedicated PUBLIC bucket 'public-assets' (images only, 5 MiB, no listing policy) for the public event/profile assets that must leave chat-images before it goes private [ROLLBACK]
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Restores the captured original policies/settings exactly (including the exposure they carried).
-- The bucket row 'public-assets' is left in place on purpose: no pack deletes any row or object.
BEGIN;
-- repo-wide pack key (same as R1 #136 / 12A / 13A): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

DO $guard$
DECLARE
  f text[] := ARRAY[]::text[];
  v text;
BEGIN
  IF current_user <> 'postgres' THEN f := f || ('run as postgres; current_user=' || current_user); END IF;
  v := coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('bucket.public-assets.public: expected true but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT');
  IF v IS DISTINCT FROM '5242880' THEN f := f || ('bucket.public-assets.limit: expected 5242880 but live is ' || v); END IF;
  v := coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT');
  IF v IS DISTINCT FROM 'image/avif,image/gif,image/jpeg,image/png,image/webp' THEN f := f || ('bucket.public-assets.mime: expected image/avif,image/gif,image/jpeg,image/png,image/webp but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT');
  IF v IS DISTINCT FROM 'public_assets_owner_admin_read' THEN f := f || ('sel.public-assets: expected public_assets_owner_admin_read but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT');
  IF v IS DISTINCT FROM 'public_assets_owner_insert' THEN f := f || ('ins.public-assets: expected public_assets_owner_insert but live is ' || v); END IF;
  v := coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_insert'), 'ABSENT');
  IF v IS DISTINCT FROM 'INSERT|authenticated|PERMISSIVE' THEN f := f || ('pol.public_assets_owner_insert.shape: expected INSERT|authenticated|PERMISSIVE but live is ' || v); END IF;
  v := coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_admin_read'), 'ABSENT');
  IF v IS DISTINCT FROM 'SELECT|authenticated|PERMISSIVE' THEN f := f || ('pol.public_assets_owner_admin_read.shape: expected SELECT|authenticated|PERMISSIVE but live is ' || v); END IF;
  v := coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_delete'), 'ABSENT');
  IF v IS DISTINCT FROM 'DELETE|authenticated|PERMISSIVE' THEN f := f || ('pol.public_assets_owner_delete.shape: expected DELETE|authenticated|PERMISSIVE but live is ' || v); END IF;
  v := coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets' AND (p.roles && ARRAY['public','anon']::name[])), 'ABSENT');
  IF v IS DISTINCT FROM '0' THEN f := f || ('pol.no_public_or_anon_policy: expected 0 but live is ' || v); END IF;
  IF array_length(f, 1) IS NOT NULL THEN
    RAISE EXCEPTION '17A ROLLBACK-P3a: DRIFT, ABORT, nothing applied. % mismatch(es): %', array_length(f, 1), array_to_string(f, ' ; ');
  END IF;
END
$guard$;

CREATE TEMP TABLE _kil17a_inv ON COMMIT DROP AS
SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('public_assets_owner_insert','public_assets_owner_admin_read','public_assets_owner_delete')), '(null)')::text AS val
UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('public-assets')), '(null)')::text AS val;

-- the bucket row is intentionally LEFT IN PLACE (no DELETE in any pack); an empty public bucket with no policies is inert. Only the three policies are dropped.
DROP POLICY public_assets_owner_insert ON storage.objects;
DROP POLICY public_assets_owner_admin_read ON storage.objects;
DROP POLICY public_assets_owner_delete ON storage.objects;

DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'bucket.public-assets.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.limit' AS name, coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.mime' AS name, coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.public-assets' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'ins.public-assets' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('bucket.public-assets.public', 'ABSENT OR true', ARRAY['ABSENT','true']::text[]),
  ('bucket.public-assets.limit', 'ABSENT OR 5242880', ARRAY['ABSENT','5242880']::text[]),
  ('bucket.public-assets.mime', 'ABSENT OR image/avif,image/gif,image/jpeg,image/png,image/webp', ARRAY['ABSENT','image/avif,image/gif,image/jpeg,image/png,image/webp']::text[]),
  ('sel.public-assets', '(none)', ARRAY['(none)']::text[]),
  ('ins.public-assets', '(none)', ARRAY['(none)']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT name, expected, actual, ok FROM r
  ) z WHERE NOT ok;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A ROLLBACK-P3a: POST-CHECK FAILED (transaction rolls back): %', bad; END IF;
END
$post$;
DO $invcheck$
DECLARE bad text;
BEGIN
  SELECT string_agg(a.name, ', ') INTO bad FROM _kil17a_inv a JOIN (
    SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('public_assets_owner_insert','public_assets_owner_admin_read','public_assets_owner_delete')), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('public-assets')), '(null)')::text AS val
  ) b USING (name) WHERE a.val IS DISTINCT FROM b.val;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A ROLLBACK-P3a: INVARIANT CHANGED (the pack must change nothing else; transaction rolls back): %', bad; END IF;
END
$invcheck$;

WITH a(name, actual) AS (
  SELECT 'bucket.public-assets.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.limit' AS name, coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.mime' AS name, coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.public-assets' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'ins.public-assets' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('bucket.public-assets.public', 'ABSENT OR true', ARRAY['ABSENT','true']::text[]),
  ('bucket.public-assets.limit', 'ABSENT OR 5242880', ARRAY['ABSENT','5242880']::text[]),
  ('bucket.public-assets.mime', 'ABSENT OR image/avif,image/gif,image/jpeg,image/png,image/webp', ARRAY['ABSENT','image/avif,image/gif,image/jpeg,image/png,image/webp']::text[]),
  ('sel.public-assets', '(none)', ARRAY['(none)']::text[]),
  ('ins.public-assets', '(none)', ARRAY['(none)']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'PRE' AS expected, 'PRE' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
COMMIT;
